        return "sol"
    if "k3" in model_text:
        return "k3"
    if any(word in model_text for word in ("glm-5.2", "deepseek-v4")):
        return "v4"
    if any(word in role_text for word in ("reviewer", "verifier", "plan_expander")):
        return "k3"
    if any(word in role_text for word in ("worker", "duty_officer", "executor", "scout")):
        return "v4"
